--
-- Table structure for table `goods`
--

DROP TABLE IF EXISTS `goods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `goods` (
  `goods_id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL DEFAULT '0' COMMENT '三级分类ID',
  `goods_name` varchar(200) NOT NULL DEFAULT '' COMMENT '商品名',
  `selling_point` varchar(255) NOT NULL DEFAULT '' COMMENT '卖点',
  `goods_image` varchar(255) NOT NULL DEFAULT '' COMMENT '主图',
  `images` text COMMENT '轮播图JSON',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '起售价',
  `line_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '划线价',
  `stock_total` int NOT NULL DEFAULT '0' COMMENT '总库存',
  `sales_total` int NOT NULL DEFAULT '0' COMMENT '总销量',
  `content` mediumtext COMMENT '商品详情',
  `spec_type` tinyint NOT NULL DEFAULT '10' COMMENT '规格 10单规格 20多规格',
  `status` tinyint NOT NULL DEFAULT '10' COMMENT '10上架 20下架',
  `is_delete` tinyint NOT NULL DEFAULT '0',
  `sort` int NOT NULL DEFAULT '100',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`goods_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=172 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品SPU';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `goods`
--

LOCK TABLES `goods` WRITE;
/*!40000 ALTER TABLE `goods` DISABLE KEYS */;
