DROP TABLE IF EXISTS `goods_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `goods_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名',
  `level` tinyint NOT NULL DEFAULT '1' COMMENT '层级 1/2/3',
  `image_url` varchar(255) NOT NULL DEFAULT '' COMMENT '分类图标',
  `sort` int NOT NULL DEFAULT '100' COMMENT '排序',
  `is_show` tinyint NOT NULL DEFAULT '1',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`category_id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品分类';
/*!40101 SET character_set_client = @saved_cs_client */;

