--
-- Table structure for table `goods_sku`
--

DROP TABLE IF EXISTS `goods_sku`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `goods_sku` (
  `sku_id` int unsigned NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL,
  `spec_sku_id` varchar(100) NOT NULL DEFAULT '' COMMENT '规格组合标识',
  `spec_text` varchar(100) NOT NULL DEFAULT '' COMMENT '规格文本 红色;XL',
  `goods_sku_no` varchar(50) NOT NULL DEFAULT '' COMMENT 'SKU编码',
  `goods_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '销售价',
  `line_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '划线价',
  `stock_num` int NOT NULL DEFAULT '0' COMMENT '库存',
  `sales_num` int NOT NULL DEFAULT '0' COMMENT '销量',
  `weight` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '重量kg',
  PRIMARY KEY (`sku_id`),
  KEY `idx_goods` (`goods_id`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品SKU';
