--
-- Table structure for table `order_info`
--

DROP TABLE IF EXISTS `order_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_info` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) NOT NULL DEFAULT '' COMMENT '订单号',
  `user_id` int NOT NULL,
  `total_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品总价',
  `coupon_money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '优惠券抵扣',
  `freight_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '运费',
  `order_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '应付金额',
  `pay_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '实付金额',
  `pay_status` tinyint NOT NULL DEFAULT '0' COMMENT '0未付 1已付 2退款',
  `pay_type` tinyint NOT NULL DEFAULT '20' COMMENT '10余额 20微信',
  `pay_time` datetime DEFAULT NULL,
  `order_status` tinyint NOT NULL DEFAULT '10' COMMENT '10待付款 20待发货 30待收货 40已完成 50已取消',
  `delivery_status` tinyint NOT NULL DEFAULT '0' COMMENT '0未发货 1已发货 2已收货',
  `delivery_time` datetime DEFAULT NULL,
  `receipt_time` datetime DEFAULT NULL,
  `consignee_name` varchar(30) NOT NULL DEFAULT '',
  `consignee_phone` varchar(20) NOT NULL DEFAULT '',
  `consignee_address` varchar(300) NOT NULL DEFAULT '' COMMENT '收货地址快照',
  `express_id` int NOT NULL DEFAULT '0',
  `express_company` varchar(30) NOT NULL DEFAULT '',
  `express_no` varchar(50) NOT NULL DEFAULT '' COMMENT '物流单号',
  `coupon_id` int NOT NULL DEFAULT '0' COMMENT '使用的用户券ID',
  `user_remark` varchar(200) NOT NULL DEFAULT '' COMMENT '买家留言',
  `cancel_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `is_delete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_user_status` (`user_id`,`order_status`)
) ENGINE=InnoDB AUTO_INCREMENT=969 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单';
/*!40101 SET character_set_client = @saved_cs_client */;

