DROP TABLE IF EXISTS `user_coupon`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_coupon` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `coupon_id` int NOT NULL,
  `name` varchar(50) NOT NULL DEFAULT '',
  `type` tinyint NOT NULL DEFAULT '10',
  `reduce_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `min_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount` decimal(3,2) NOT NULL DEFAULT '1.00',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0未使用 1已使用 2已过期',
  `order_id` int NOT NULL DEFAULT '0',
  `receive_time` datetime DEFAULT NULL,
  `expire_time` datetime DEFAULT NULL,
  `use_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户优惠券';
